package com.arena.core.facility;
import com.arena.core.exception.*;import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.web.method.support.*;import org.springframework.core.MethodParameter;import org.springframework.web.context.request.NativeWebRequest;import org.springframework.web.bind.support.WebDataBinderFactory;
import org.springframework.security.oauth2.jwt.Jwt;import java.util.*;
import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class FacilityControllerTest {
 FacilityService service=mock(FacilityService.class);MockMvc mvc;ObjectMapper json=new ObjectMapper();Jwt jwt=Jwt.withTokenValue("unit").header("alg","none").subject("owner").build();
 @BeforeEach void setup(){mvc=MockMvcBuilders.standaloneSetup(new FacilityController(service)).setControllerAdvice(new GlobalExceptionHandler()).setCustomArgumentResolvers(new HandlerMethodArgumentResolver(){public boolean supportsParameter(MethodParameter p){return p.getParameterType()==Jwt.class;}public Object resolveArgument(MethodParameter p,ModelAndViewContainer m,NativeWebRequest r,WebDataBinderFactory b){return jwt;}}).build();when(service.parse(any())).thenAnswer(i->json.readTree((byte[])i.getArgument(0)));}
 @Test void bulkPostMappingAcceptsUuidAndReturnsGeneratedRows()throws Exception{when(service.create(eq(jwt),eq(10L),eq(20L),any(),any())).thenReturn(new FacilityContracts.Result(List.of(new FacilityContracts.View(101L,20L,"E1","ENGLISH",null,null,null,true,false,0L))));mvc.perform(post("/api/v1/academies/10/sports/20/facilities/bulk").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"facilities\":[{\"facilityType\":\"ENGLISH\",\"count\":1}]}" )).andExpect(status().isCreated()).andExpect(jsonPath("$.facilities[0].facilityId").value(101)).andExpect(jsonPath("$.facilities[0].configured").value(false));}
 @Test void idempotencyHeaderIsMandatoryAndMustBeUuid()throws Exception{mvc.perform(post("/api/v1/academies/10/sports/20/facilities/bulk").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/academies/10/sports/20/facilities/bulk").header("Idempotency-Key","invalid").contentType("application/json").content("{}")).andExpect(status().isBadRequest());verify(service,never()).create(any(),any(),any(),any(),any());}
 @Test void conflictDetailsAndReasonAreSafeAndStructured()throws Exception{when(service.patch(any(),eq(10L),any())).thenThrow(new FacilityFailure(ErrorCode.FACILITY_VERSION_CONFLICT,"STALE_VERSION",Map.of(),List.of(Map.of("facilityId",103L,"code","E3","submittedVersion",2L,"currentVersion",3L))));mvc.perform(patch("/api/v1/academies/10/facilities/bulk").contentType("application/json").content("{\"facilities\":[]}")).andExpect(status().isConflict()).andExpect(jsonPath("$.reasonCode").value("STALE_VERSION")).andExpect(jsonPath("$.conflicts[0].code").value("E3"));}
}
